class Solution {
  public int minLength(String s, int numOps) {
    int n = s.length(), lo = 1, hi = n;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (flips(s, mid) <= numOps) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  private static int flips(String s, int limit) {
    int n = s.length();
    if (limit == 1) {
      int diff = 0;
      for (int i = 0; i < n; i++) if (s.charAt(i) - '0' != (i & 1)) diff++;
      return Math.min(diff, n - diff);
    }
    int ops = 0;
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && s.charAt(j) == s.charAt(i)) j++;
      ops += (j - i) / (limit + 1);
      i = j;
    }
    return ops;
  }
}
